const {entrada:e,config:c}=$input.first().json;
const id=e.metadata?.['message-id']||e.messageId;
if(typeof id!=='string'||!id.trim()||id.length>300||!c.CUENTA_BUZON)throw new Error('Correo sin identidad estable');
const text=e.textPlain||e.text,subject=e.subject||'';
if(typeof text!=='string'||text.length>20000||!text.trim()||typeof subject!=='string'||subject.length>500)throw new Error('Contenido de correo no válido');
if(c.MODELO_EXTRACCION!=='openrouter/free')throw new Error('Solo está autorizado openrouter/free');
return [{json:{clave:`correo:${c.CUENTA_BUZON}:${id}`,id,text,subject,config:c}}];

const cent=v=>{if(!/^(0|[1-9]\d*)(\.\d{1,2})?$/.test(String(v)))throw new Error('Importe inválido');const [a,b='']=String(v).split('.');const n=Number(a)*100+Number(b.padEnd(2,'0'));if(!Number.isSafeInteger(n))throw new Error('Importe fuera de rango');return n;};
const add=(a,b)=>{const n=a+b;if(!Number.isSafeInteger(n))throw new Error('Total fuera de rango');return n;};
const euros=n=>(n/100).toFixed(2)+' EUR';
const date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v;
const medios=['efectivo','tarjeta','bizum','transferencia'];
const list=(r,requireCount=false)=>{if(r.statusCode!==200||!Array.isArray(r.body))throw new Error('Respuesta API incompleta');if(requireCount&&Number(r.headers?.['x-total-count'])!==r.body.length)throw new Error('Lista API incompleta');return r.body;};
const totals=(rows,desde,hasta)=>{const by={efectivo:0,tarjeta:0,bizum:0};const ids=new Set();let total=0;for(const r of rows){if(!Number.isSafeInteger(r.id)||r.id<1||ids.has(r.id)||!date(r.fecha)||r.fecha<desde||r.fecha>hasta||!medios.includes(r.forma_pago))throw new Error('Movimiento API inválido');ids.add(r.id);const n=cent(r.importe);if(n<=0)throw new Error('Movimiento sin importe positivo');by[r.forma_pago]=add(by[r.forma_pago]||0,n);total=add(total,n);}return {total,by};};

const mail=$('Preparar extracción').first().json;let e;
try{e=JSON.parse($input.first().json.choices[0].message.content);}catch{throw new Error('Extracción IA no es JSON válido');}
if(!e||typeof e.es_pago!=='boolean')throw new Error('Esquema IA inválido');if(!e.es_pago)return [];
if(typeof e.ordenante!=='string'||!e.ordenante.trim()||e.ordenante.length>200||typeof e.importe!=='number'||cent(e.importe)<=0||!['bizum','transferencia'].includes(e.medio)||(e.concepto!==null&&typeof e.concepto!=='string')||(e.apartado_id!==null&&(!Number.isSafeInteger(e.apartado_id)||e.apartado_id<1)))throw new Error('Campos IA inválidos');
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const field=name=>mail.text.match(new RegExp('^'+name+'[ .:]+([^\\r\\n]+)','im'))?.[1]?.trim();
const amount=field('Importe')?.match(/^(\d+)[,.](\d{2})\s*(EUR|€)$/i);
const explicit=String(field('Concepto')||'').match(/\bapartado\s*(?:n[ºo.]?\s*)?#?\s*(\d+)\b/i);
const sourceId=explicit?Number(explicit[1]):null;
if(!amount||cent(e.importe)!==cent(amount[1]+'.'+amount[2])||norm(e.ordenante)!==norm(field('Ordenante'))||norm(e.concepto)!==norm(field('Concepto'))||e.apartado_id!==sourceId||!norm(mail.text+' '+mail.subject).includes(e.medio))throw new Error('Extracción no concuerda con el aviso original');
return [{json:{...e,clave:mail.clave,importe_centimos:cent(e.importe)}}];

