const e=$('Validar extracción').first().json,c=$('Preparar extracción').first().json.config;
const rows=list($input.first().json,true),today=$now.setZone('Europe/Madrid').toISODate();
const tokens=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().match(/[a-z]+/g)||[];
const bank=tokens(e.ordenante);
const agrees=(a,initials=false)=>{const names=tokens(a.cliente);return names.length>=2&&bank.length>=2&&names.length<=bank.length&&names.every((x,i)=>x===bank[i]||(initials&&bank[i].length===1&&x.startsWith(bank[i])));};
let candidates=e.apartado_id?rows.filter(a=>a.id===e.apartado_id&&agrees(a,true)):rows.filter(a=>agrees(a,false));
let reason='identidad_insuficiente',a=candidates.length===1?candidates[0]:null;
if(!a&&!e.apartado_id){const possible=rows.filter(a=>agrees(a,true));if(possible.length===1&&e.importe_centimos>cent(possible[0].pendiente))reason='importe_superior_al_pendiente';}
if(a){if(a.estado!=='activo')reason='apartado_no_activo';else if(!date(a.fecha_limite)||today>a.fecha_limite)reason='plazo_vencido';else if(e.importe_centimos>cent(a.pendiente))reason='importe_superior_al_pendiente';else reason=null;}
return [{json:{clave:e.clave,apartado_id:a?.id||null,importe:e.importe,forma_pago:e.medio,puede_abonar:reason===null,motivo:reason,config:c}}];

