const previous=$('Decidir pago').first().json,r=$input.first().json;
if(r.statusCode!==200||r.body?.id!==previous.apartado_id)throw new Error('Saldo no disponible; conciliación necesaria');
const a=r.body,today=$now.setZone('Europe/Madrid').toISODate();
let motivo=null;if(a.estado!=='activo')motivo='apartado_no_activo';else if(!date(a.fecha_limite)||today>a.fecha_limite)motivo='plazo_vencido';else if(cent(previous.importe)>cent(a.pendiente))motivo='importe_superior_al_pendiente';
return [{json:{...previous,puede_abonar:motivo===null,motivo}}];

const d=$input.first().json;
const reasons={identidad_insuficiente:'No hay un apartado inequívoco. Solicitar identificación a quien pagó.',importe_superior_al_pendiente:'El importe supera el saldo pendiente. Revisar el aviso con Marisa.',plazo_vencido:'El apartado está fuera de plazo. No se registra el abono.',apartado_no_activo:'El apartado ya no admite abonos.',rechazado_api:'La API rechazó el pago; revisar la ejecución sin reintentar.'};
return [{json:{clave:d.clave,documento:{apartado_id:d.apartado_id,motivo:d.motivo,destinatario:d.config.CORREO_MARISA,remitente:d.config.CORREO_REMITENTE,asunto:'Paso Firme · Pago pendiente de revisión',texto:`Referencia del correo: ${d.clave}\nApartado: ${d.apartado_id||'sin identificar'}\nMotivo: ${reasons[d.motivo]||'Se necesita revisión humana.'}\nNo se ha creado un abono.`}}}];
